 import React, { useState, useEffect } from 'react'
import { useParams, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import FollowButton from '../components/follow/FollowButton'
import { Users, UserPlus, ArrowLeft } from 'lucide-react'

export default function Followers() {
    const { userId, type } = useParams() // type: 'followers' or 'following'
    const { user } = useAuth()
    const [users, setUsers] = useState([])
    const [loading, setLoading] = useState(true)
    const [profile, setProfile] = useState(null)
    const [error, setError] = useState(null)

    useEffect(() => {
        if (userId && type) {
            loadData()
        }
    }, [userId, type])

    const loadData = async () => {
        setLoading(true)
        setError(null)
        try {
            // Get user profile
            const { data: profileData, error: profileError } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url')
                .eq('id', userId)
                .single()

            if (profileError) throw profileError
            setProfile(profileData)

            // Get followers or following based on type
            let query
            if (type === 'followers') {
                // For followers: users who follow this user
                // We need to get the follower_id (who is following)
                query = supabase
                    .from('followers')
                    .select(`
                        follower_id,
                        profiles:follower_id (
                            id,
                            username,
                            full_name,
                            avatar_url,
                            is_verified
                        )
                    `)
                    .eq('following_id', userId)
            } else {
                // For following: users this user follows
                // We need to get the following_id (who they follow)
                query = supabase
                    .from('followers')
                    .select(`
                        following_id,
                        profiles:following_id (
                            id,
                            username,
                            full_name,
                            avatar_url,
                            is_verified
                        )
                    `)
                    .eq('follower_id', userId)
            }

            const { data, error } = await query

            if (error) throw error

            // Extract the user data from the nested structure
            let userList = []
            if (data) {
                userList = data.map(item => {
                    if (type === 'followers') {
                        return item.profiles // profiles is the follower
                    } else {
                        return item.profiles // profiles is the following
                    }
                }).filter(Boolean) // Remove any null values
            }
            
            setUsers(userList)
        } catch (error) {
            console.error('Error loading followers:', error)
            setError(error.message || 'Failed to load data')
        } finally {
            setLoading(false)
        }
    }

    if (loading) {
        return (
            <div className="max-w-2xl mx-auto px-4 py-6">
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading...</div>
                </div>
            </div>
        )
    }

    if (error) {
        return (
            <div className="max-w-2xl mx-auto px-4 py-6">
                <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
                    Error: {error}
                </div>
            </div>
        )
    }

    return (
        <div className="max-w-2xl mx-auto px-4 py-6">
            {/* Header */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                <div className="flex items-center gap-3">
                    <Link 
                        to={`/profile/${userId}`}
                        className="p-2 hover:bg-gray-100 rounded-lg transition"
                    >
                        <ArrowLeft size={20} className="text-gray-600" />
                    </Link>
                    <div>
                        <h1 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                            {type === 'followers' ? (
                                <Users size={20} className="text-gray-500" />
                            ) : (
                                <UserPlus size={20} className="text-gray-500" />
                            )}
                            {type === 'followers' ? 'Followers' : 'Following'}
                        </h1>
                        <p className="text-sm text-gray-500">
                            @{profile?.username || 'user'}
                        </p>
                    </div>
                </div>
            </div>

            {/* Users List */}
            {users.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">👀</div>
                    <p className="text-gray-500 text-lg">
                        {type === 'followers' 
                            ? 'No followers yet' 
                            : 'Not following anyone yet'}
                    </p>
                    <p className="text-gray-400 text-sm mt-1">
                        {type === 'followers' 
                            ? 'When people follow you, they\'ll appear here' 
                            : 'Follow other users to see them here'}
                    </p>
                </div>
            ) : (
                <div className="space-y-2">
                    {users.map((userItem) => (
                        <div 
                            key={userItem.id} 
                            className="bg-white rounded-xl shadow-md p-4 flex items-center justify-between hover:shadow-lg transition"
                        >
                            <Link 
                                to={`/profile/${userItem.id}`} 
                                className="flex items-center gap-3 hover:opacity-80 flex-1"
                            >
                                <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold text-sm overflow-hidden">
                                    {userItem.avatar_url ? (
                                        <img 
                                            src={userItem.avatar_url} 
                                            alt={userItem.username} 
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        userItem.username?.[0]?.toUpperCase() || 'U'
                                    )}
                                </div>
                                <div>
                                    <div className="font-semibold text-gray-800 flex items-center gap-1.5">
                                        {userItem.full_name || userItem.username}
                                        {userItem.is_verified && (
                                            <span className="text-blue-500 text-sm">✓</span>
                                        )}
                                    </div>
                                    <div className="text-sm text-gray-500">@{userItem.username}</div>
                                </div>
                            </Link>
                            {userItem.id !== user?.id && (
                                <FollowButton 
                                    userId={userItem.id} 
                                    username={userItem.username}
                                    onFollowChange={loadData}
                                />
                            )}
                        </div>
                    ))}

                    {/* Total count */}
                    <div className="text-center text-sm text-gray-400 mt-4">
                        {users.length} {type === 'followers' ? 'followers' : 'following'}
                    </div>
                </div>
            )}
        </div>
    )
}
